#include <bits/stdc++.h>
using namespace std;

int main() {
	ios::sync_with_stdio(false);
	cin.tie(nullptr);
	int t;
	cin >> t;
	while (t--) {
		int n, m;
		cin >> n >> m;
		vector<int> cnt(m + 1);
		long long total = 0;
		for (int i = 0; i < n; i++) {
			int a;
			cin >> a;
			cnt[a]++;
			total += a;
		}
		vector<int> pref(m + 1);
		for (int v = 1; v <= m; v++) {
			pref[v] = pref[v - 1] + cnt[v];
		}
		auto range_sum = [&](int l, int r) -> int {
			if (l > r || l > m) {
				return 0;
			}
			r = min(r, m);
			l = max(l, 1);
			return pref[r] - pref[l - 1];
		};

		vector<long long> ans(m + 1);
		int max_k = 0;
		while (max_k < 30 && (1 << max_k) <= m) {
			max_k++;
		}
		// max_k is largest k with 2^k <= m; for larger k answer is total
		for (int k = 1; k <= m; k++) {
			if (k > max_k) {
				ans[k] = total;
				continue;
			}
			int lim = 1 << k;
			long long best = 0;
			int xmax = m / lim;
			for (int x = 1; x <= xmax; x++) {
				long long cur = 0;
				for (int y = 1; y < lim; y++) {
					int L = y * x;
					if (L > m) {
						break;
					}
					int R = min(m, (y + 1) * x - 1);
					cur += 1LL * y * range_sum(L, R);
				}
				int L = lim * x;
				if (L <= m) {
					cur += 1LL * (lim - 1) * range_sum(L, m);
					cur += cnt[L];
				}
				best = max(best, cur);
			}
			// When lim > m, xmax = 0; still need x = 1 case covered by total below
			if (lim - 1 >= m) {
				best = total;
			} else if (xmax == 0) {
				// 2^k > m should already be handled; keep safe fallback for x = 1
				long long cur = 0;
				for (int y = 1; y < lim; y++) {
					if (y > m) {
						break;
					}
					int R = min(m, y); // x = 1: [y, y]
					cur += 1LL * y * range_sum(y, y);
				}
				best = max(best, cur);
			}
			ans[k] = best;
		}
		for (int k = 1; k <= m; k++) {
			cout << ans[k] << " \n"[k == m];
		}
	}
	return 0;
}

